//! App-owned theme files only. No caller-provided directory or external path.
use serde::{Serialize,Deserialize};
use sha2::{Digest,Sha256};
use std::{fs::{self,OpenOptions},io::{Read,Write},path::{Path,PathBuf}};
use tauri::Manager;
const MAX_FILES:usize=50;
const MAX_BYTES:u64=65536;
const SLOTS:&[&str]=&["color-bg-1","color-bg-2","color-bg-3","color-card","color-card-hover","color-card-active","color-tab","color-tab-hover","color-tab-active","color-buy","color-buy-hover","color-buy-active","color-sell","color-sell-hover","color-sell-active","color-navigation","color-navigation-hover","color-navigation-active","color-text","color-text-bg","color-icons","color-icons-bg"];
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(rename_all="camelCase")]
pub struct ThemePreset{pub name:String,pub author:String,#[serde(default)]pub icon_base64:String,pub color_data:String,#[serde(default)]pub creation_date:Option<String>}
#[derive(Clone,Debug,Serialize)]#[serde(rename_all="camelCase")]pub struct ThemeFile{pub file_name:String,pub content:String}
#[derive(Debug,Serialize)]#[serde(rename_all="camelCase")]pub struct ThemeError{pub file_name:String,pub error:String}
#[derive(Debug,Serialize)]#[serde(rename_all="camelCase")]pub struct ThemeLibrary{pub files:Vec<ThemeFile>,pub errors:Vec<ThemeError>}
fn is_link(metadata:&fs::Metadata)->bool{
 #[cfg(windows)]{use std::os::windows::fs::MetadataExt;metadata.file_type().is_symlink()||metadata.file_attributes()&0x400!=0}
 #[cfg(not(windows))]{metadata.file_type().is_symlink()}
}
fn directory(base:&Path)->Result<PathBuf,String>{
 fs::create_dir_all(base).map_err(|_|"无法创建应用数据目录")?;let base_meta=fs::symlink_metadata(base).map_err(|_|"应用数据目录不可用")?;if is_link(&base_meta)||!base_meta.is_dir(){return Err("应用数据目录不能是链接".into());}let base=base.canonicalize().map_err(|_|"应用数据目录不可用")?;let path=base.join("themes");
 match fs::symlink_metadata(&path){Ok(meta)=>{if is_link(&meta)||!meta.is_dir(){return Err("主题目录不能是链接或文件".into());}},Err(e)if e.kind()==std::io::ErrorKind::NotFound=>fs::create_dir(&path).map_err(|_|"无法创建主题目录")?,Err(_)=>return Err("主题目录不可用".into())}
 let canonical=path.canonicalize().map_err(|_|"主题目录不可用")?;if canonical.parent()!=Some(base.as_path()){return Err("主题目录超出应用范围".into());}Ok(canonical)
}
fn icon_bytes(value:&str)->Result<Vec<u8>,String>{
 if value.is_empty(){return Ok(vec![]);}if value.len()>22000||value.len()%4!=0{return Err("图标超过15KB或格式无效".into());}
 let digit=|c:u8|->Option<u32>{match c{b'A'..=b'Z'=>Some(u32::from(c-b'A')),b'a'..=b'z'=>Some(u32::from(c-b'a')+26),b'0'..=b'9'=>Some(u32::from(c-b'0')+52),b'+'=>Some(62),b'/'=>Some(63),_=>None}};
 let mut bytes=vec![];for (index,chunk)in value.as_bytes().chunks_exact(4).enumerate(){let a=digit(chunk[0]).ok_or("图标编码无效")?;let b=digit(chunk[1]).ok_or("图标编码无效")?;let last=(index+1)*4==value.len();if chunk[2]==b'='&&!last||chunk[3]==b'='&&!last||chunk[2]==b'='&&chunk[3]!=b'='{return Err("图标编码无效".into());}let c=if chunk[2]==b'='{0}else{digit(chunk[2]).ok_or("图标编码无效")?};let d=if chunk[3]==b'='{0}else{digit(chunk[3]).ok_or("图标编码无效")?};let n=a<<18|b<<12|c<<6|d;bytes.push((n>>16)as u8);if chunk[2]!=b'='{bytes.push((n>>8)as u8);}if chunk[3]!=b'='{bytes.push(n as u8);}}
 if bytes.len()>15000||bytes.len()<24||&bytes[..8]!=b"\x89PNG\r\n\x1a\n"||&bytes[12..16]!=b"IHDR"{return Err("图标必须是15KB以内PNG".into());}let w=u32::from_be_bytes(bytes[16..20].try_into().unwrap());let h=u32::from_be_bytes(bytes[20..24].try_into().unwrap());if !(1..=512).contains(&w)||!(1..=512).contains(&h){return Err("主题图标尺寸无效".into());}Ok(bytes)
}
fn validated(mut preset:ThemePreset)->Result<ThemePreset,String>{
 if preset.name.trim().is_empty()||preset.name.encode_utf16().count()>64||preset.author.encode_utf16().count()>64||preset.name.chars().any(char::is_control)||preset.author.chars().any(char::is_control){return Err("主题名称或作者无效".into());}preset.name=preset.name.trim().into();preset.author=preset.author.trim().into();
 if preset.color_data.len()>16384{return Err("主题颜色文本过大".into());}let mut seen=std::collections::BTreeSet::new();let mut colors=vec![];
 for line in preset.color_data.lines().map(str::trim).filter(|s|!s.is_empty()){let(key,value)=line.split_once(':').ok_or("主题颜色格式无效")?;let key=key.trim().strip_prefix("--").ok_or("主题颜色字段无效")?;if !SLOTS.contains(&key)||!seen.insert(key.to_owned()){return Err("主题颜色字段未知或重复".into());}let value=value.trim().strip_suffix(';').unwrap_or(value.trim()).trim();if value.len()!=7||!value.starts_with('#')||!value[1..].bytes().all(|b|b.is_ascii_hexdigit()){return Err("主题颜色必须是六位十六进制颜色".into());}colors.push(format!("--{key}: {};",value.to_ascii_lowercase()));}
 if colors.is_empty(){return Err("主题颜色为空".into());}preset.color_data=colors.join("\r\n");icon_bytes(&preset.icon_base64)?;
 if let Some(date)=&preset.creation_date{if date.len()>64||chrono::DateTime::parse_from_rfc3339(date).is_err(){return Err("主题日期无效".into());}}else{preset.creation_date=Some(chrono::Utc::now().to_rfc3339());}Ok(preset)
}
fn safe_name(value:&str)->bool{!value.is_empty()&&value.len()<=240&&value.ends_with(".alecatheme")&&!value.starts_with('.')&&value.chars().all(|c|!c.is_control()&&!"/\\:<>|?*".contains(c))}
fn read_file(dir:&Path,name:&str)->Result<ThemeFile,String>{
 if !safe_name(name){return Err("主题文件名无效".into());}let path=dir.join(name);let meta=fs::symlink_metadata(&path).map_err(|_|"主题文件不可读")?;if is_link(&meta)||!meta.is_file()||meta.len()>MAX_BYTES{return Err("主题文件不能是链接且必须小于64KB".into());}
 let mut options=OpenOptions::new();options.read(true);#[cfg(windows)]{use std::os::windows::fs::OpenOptionsExt;options.custom_flags(0x00200000);}let file=options.open(path).map_err(|_|"主题文件不可读")?;let opened=file.metadata().map_err(|_|"主题文件不可读")?;if is_link(&opened)||!opened.is_file(){return Err("主题文件不能是链接".into());}
 let mut content=String::new();file.take(MAX_BYTES+1).read_to_string(&mut content).map_err(|_|"主题文件不是有效UTF-8")?;if content.len()>MAX_BYTES as usize{return Err("主题文件过大".into());}let preset:ThemePreset=serde_json::from_str(content.trim_start_matches('\u{feff}')).map_err(|_|"主题JSON无效")?;let preset=validated(preset)?;
 Ok(ThemeFile{file_name:name.into(),content:serde_json::to_string(&preset).map_err(|_|"主题序列化失败")?})
}
fn list_at(base:&Path)->Result<ThemeLibrary,String>{let dir=directory(base)?;let mut names=vec![];for (index,entry)in fs::read_dir(&dir).map_err(|_|"主题目录不可读")?.enumerate(){if index>=500{return Err("主题目录文件过多".into());}let entry=entry.map_err(|_|"主题目录不可读")?;let Some(name)=entry.file_name().to_str().map(str::to_owned)else{continue;};if name.ends_with(".alecatheme"){names.push(name);}}if names.len()>MAX_FILES{return Err("主题目录最多支持50个主题".into());}names.sort();let mut files=vec![];let mut errors=vec![];for name in names{match read_file(&dir,&name){Ok(file)=>files.push(file),Err(error)=>errors.push(ThemeError{file_name:name,error})}}Ok(ThemeLibrary{files,errors})}
fn save_at(base:&Path,preset:ThemePreset)->Result<ThemeFile,String>{let preset=validated(preset)?;let dir=directory(base)?;let name=format!("{:x}.alecatheme",Sha256::digest(format!("{}\0{}",preset.name,preset.author).as_bytes()));let target=dir.join(&name);if let Ok(meta)=fs::symlink_metadata(&target){if is_link(&meta)||!meta.is_file(){return Err("目标主题文件不能是链接".into());}}else{let entries=fs::read_dir(&dir).map_err(|_|"主题目录不可读")?.take(501).collect::<Result<Vec<_>,_>>().map_err(|_|"主题目录不可读")?;if entries.len()>500{return Err("主题目录文件过多".into());}let count=entries.iter().filter(|entry|entry.file_name().to_string_lossy().ends_with(".alecatheme")).count();if count>=MAX_FILES{return Err("最多保存50个主题".into());}}
 let content=serde_json::to_string_pretty(&preset).map_err(|_|"主题序列化失败")?;if content.len()>MAX_BYTES as usize{return Err("主题文件过大".into());}let temp=dir.join(format!(".theme-{}-{}.tmp",std::process::id(),chrono::Utc::now().timestamp_nanos_opt().unwrap_or_default()));
 let result:Result<(),String>=(||{let mut file=OpenOptions::new().write(true).create_new(true).open(&temp).map_err(|_|"无法创建主题临时文件")?;file.write_all(content.as_bytes()).map_err(|_|"主题写入失败")?;file.sync_all().map_err(|_|"主题写入失败")?;drop(file);fs::rename(&temp,&target).map_err(|_|"主题替换失败")?;Ok(())})();if result.is_err(){let _=fs::remove_file(temp);}result?;Ok(ThemeFile{file_name:name,content})
}
fn delete_at(base:&Path,name:&str)->Result<(),String>{let dir=directory(base)?;read_file(&dir,name)?;fs::remove_file(dir.join(name)).map_err(|_|"主题删除失败".into())}
fn app_base(app:&tauri::AppHandle)->Result<PathBuf,String>{app.path().app_data_dir().map_err(|_|"应用数据目录不可用".into())}
#[tauri::command]pub fn theme_presets_list(app:tauri::AppHandle)->Result<ThemeLibrary,String>{list_at(&app_base(&app)?)}
#[tauri::command]pub fn theme_presets_save(preset:ThemePreset,app:tauri::AppHandle)->Result<ThemeFile,String>{save_at(&app_base(&app)?,preset)}
#[tauri::command]pub fn theme_presets_delete(file_name:String,app:tauri::AppHandle)->Result<(),String>{delete_at(&app_base(&app)?,&file_name)}
#[tauri::command]pub fn theme_presets_open(app:tauri::AppHandle)->Result<(),String>{let dir=directory(&app_base(&app)?)?;open_directory(&dir)}
#[cfg(windows)]fn open_directory(dir:&Path)->Result<(),String>{use std::os::windows::ffi::OsStrExt;let operation:Vec<u16>="open".encode_utf16().chain(Some(0)).collect();let path:Vec<u16>=dir.as_os_str().encode_wide().chain(Some(0)).collect();#[link(name="shell32")]extern "system"{fn ShellExecuteW(window:*mut std::ffi::c_void,verb:*const u16,file:*const u16,params:*const u16,directory:*const u16,show:i32)->isize;}let result=unsafe{ShellExecuteW(std::ptr::null_mut(),operation.as_ptr(),path.as_ptr(),std::ptr::null(),std::ptr::null(),1)};if result<=32{Err("无法打开主题目录".into())}else{Ok(())}}
#[cfg(not(windows))]fn open_directory(_: &Path)->Result<(),String>{Err("此平台尚未配置主题目录打开方式".into())}
#[cfg(test)]mod tests{use super::*;
 fn root()->PathBuf{let dir=std::env::temp_dir().join(format!("myframe-theme-test-{}-{}",std::process::id(),chrono::Utc::now().timestamp_nanos_opt().unwrap()));fs::create_dir_all(&dir).unwrap();dir}
 fn preset()->ThemePreset{ThemePreset{name:"Synthetic theme".into(),author:"Fixture".into(),icon_base64:String::new(),color_data:SLOTS.iter().map(|key|format!("--{key}: #123456;")).collect::<Vec<_>>().join("\n"),creation_date:None}}
 #[test]fn own_directory_stable_hash_roundtrip_replace_and_remove(){let base=root();let a=save_at(&base,preset()).unwrap();assert_eq!(a.file_name.len(),75);assert!(base.join("themes").join(&a.file_name).is_file());assert_eq!(list_at(&base).unwrap().files.len(),1);let mut edited=preset();edited.color_data="--color-buy: #abcdef;".into();let b=save_at(&base,edited).unwrap();assert_eq!(a.file_name,b.file_name);assert_eq!(list_at(&base).unwrap().files.len(),1);assert!(b.content.contains("#abcdef"));delete_at(&base,&b.file_name).unwrap();assert!(list_at(&base).unwrap().files.is_empty());fs::remove_dir_all(base).unwrap();}
 #[test]fn hand_placed_files_are_read_and_invalid_files_reported_without_raw_content(){let base=root();let dir=directory(&base).unwrap();let mut value=serde_json::to_value(preset()).unwrap();value["secret"]=serde_json::json!("DO_NOT_RETURN");fs::write(dir.join("manual.alecatheme"),value.to_string()).unwrap();fs::write(dir.join("broken.alecatheme"),"PRIVATE_INPUT_BAD_JSON").unwrap();let list=list_at(&base).unwrap();assert_eq!(list.files.len(),1);assert_eq!(list.errors.len(),1);assert!(!list.files[0].content.contains("DO_NOT_RETURN"));assert!(!list.errors[0].error.contains("PRIVATE_INPUT"));for name in ["../outside.alecatheme","C:\\outside.alecatheme",".hidden.alecatheme","x.json"]{assert!(read_file(&dir,name).is_err());assert!(delete_at(&base,name).is_err());}fs::remove_dir_all(base).unwrap();}
 #[test]fn bounds_and_css_rejection_preserve_prior_theme(){let base=root();let a=save_at(&base,preset()).unwrap();for color in ["--color-buy: url(https://example.com);","--unknown: #abcdef;","--color-buy: #abcdef;\n--color-buy: #123456;"]{let mut p=preset();p.color_data=color.into();assert!(save_at(&base,p).is_err());}let mut p=preset();p.icon_base64="x".repeat(22001);assert!(save_at(&base,p).is_err());assert_eq!(list_at(&base).unwrap().files.len(),1);assert_eq!(read_file(&directory(&base).unwrap(),&a.file_name).unwrap().file_name,a.file_name);let dir=directory(&base).unwrap();fs::write(dir.join("huge.alecatheme"),vec![b' ';MAX_BYTES as usize+1]).unwrap();assert_eq!(list_at(&base).unwrap().errors.len(),1);fs::remove_dir_all(base).unwrap();}
 #[test]fn file_count_is_bounded(){let base=root();let dir=directory(&base).unwrap();for i in 0..51{fs::write(dir.join(format!("{i}.alecatheme")),"{}").unwrap();}assert!(list_at(&base).is_err());assert!(save_at(&base,preset()).is_err());fs::remove_dir_all(base).unwrap();}
 #[test]fn linked_theme_files_never_read_or_modify_external_target(){let base=root();let dir=directory(&base).unwrap();let outside=base.join("outside.json");fs::write(&outside,serde_json::to_string(&preset()).unwrap()).unwrap();let link=dir.join("linked.alecatheme");#[cfg(windows)]let result=std::os::windows::fs::symlink_file(&outside,&link);#[cfg(unix)]let result=std::os::unix::fs::symlink(&outside,&link);if result.is_err(){eprintln!("symlink creation unavailable; link-specific OS case NOT_RUN");}if result.is_ok(){assert!(read_file(&dir,"linked.alecatheme").is_err());assert!(delete_at(&base,"linked.alecatheme").is_err());assert!(outside.is_file());fs::remove_file(link).unwrap();}fs::remove_dir_all(base).unwrap();}
}
